SELECT COUNT(*) FROM projects


        AND name LIKE CONCAT('%', #{name}, '%')


        AND leader = #{leader}

SELECT id, name, status, leader, progress, create_time, description FROM projects


        AND name LIKE CONCAT('%', #{name}, '%')


        AND leader = #{leader}


ORDER BY create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM projects p
JOIN project_user pu ON pu.project_id = p.id AND pu.user_id = #{userId}


        AND p.name LIKE CONCAT('%', #{name}, '%')


        AND p.leader = #{leader}

SELECT p.id, p.name, p.status, p.leader, p.progress, p.create_time, p.description
FROM projects p
JOIN project_user pu ON pu.project_id = p.id AND pu.user_id = #{userId}


        AND p.name LIKE CONCAT('%', #{name}, '%')


        AND p.leader = #{leader}


ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{pageSize}
